#!/usr/bin/env bash
# Intuitive: adds a one-line style reminder to every prompt so long sessions never drift.
# Generated by scripts/build.mjs from shared/*.md. Edit those files, then rebuild.
# Turn off with `/plugin configure intuitive@intuitive` (reminder = false), or set
# INTUITIVE_REMINDER=off in the "env" block of a settings.json (the env var wins when set).
setting="${INTUITIVE_REMINDER:-${CLAUDE_PLUGIN_OPTION_REMINDER:-on}}"
case "$(printf '%s' "$setting" | tr '[:upper:]' '[:lower:]')" in
  false | off | 0 | no | disabled) exit 0 ;;
esac
cat <<'JSON'
{"hookSpecificOutput":{"hookEventName":"UserPromptSubmit","additionalContext":"Intuitive output style (active): do what the user would expect here. Answer questions, act on clear requests without needless check-ins, stay within what was asked, and lead with the answer, sized to the question."}}
JSON
